from taf.transport.ssh import connect
from socket import timeout as timeout_exception
from time import time

import logging
logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class RemoteShell(object):
    """Simplifies interaction with remote ssh shell."""

    def __init__(self, hostname, username, password, port=None, timeout=None):
        self._hostname = hostname
        self._username = username
        self._password = password
        self._port = port
        self._ssh_connection = None
        self._shell = None
        self._timeout = timeout

    def connect(self):
        logger.debug("Spawning (connecting to) new remote shell.")

        if self._ssh_connection is None:
            self._ssh_connection = connect(self._hostname, self._username,
                                           self._password, port=self._port,
                                           timeout=self._timeout)
        if not self._ssh_connection.is_connected:
            self._ssh_connection.connect()
        self._shell = self._ssh_connection.invoke_shell()

    def disconnect(self):
        logger.debug("Disconnecting remote shell.")

        if self._ssh_connection is None:
            return

        self._ssh_connection.disconnect()
        self._ssh_connection = None

    def sendall(self, s):
        logger.debug("Sending input: {0!r}".format(s))

        if self._ssh_connection is None:
            raise RuntimeError("cannot send: not connected.")
        self._shell.sendall(s)

    def sendline(self, s):
        """Send input with a carriage return at the end."""
        self.sendall(s + '\r\n')

    def read_nonblocking(self):
        if self._shell is None:
            raise RuntimeError("cannot receive: not connected.")
        received = self._receive(self._shell)

        logger.debug("Received output: {0!r}".format(received))
        return received

    @staticmethod
    def _receive(channel):
        received = bytearray()
        while channel.recv_ready():
            received += channel.recv(1)
        return received.decode()

    def expect_exact(self, match, timeout=10):
        """Read from the shell until a given match is encountered.

        If the given string is not encountered in the amount of time specified
        by timout parameter, socket.timeout is raised.

        :param match:
            The string to look for while reading.
        :type match: ``str``
        :param timeout:
            Timeout in seconds. 10 by default.
        :type timeout: ``float`` or ``None``
        :raises socket.timeout:
        :returns:
            Output from the shell, up to and including the given string.
        :rtype: ``str``
        """
        # XXX: The pexpect's expect_exact semantics differ from this one.
        # TODO: Unittests.
        # TODO: This is copied from taf.transport.ssh. It should be a part of
        # what Connection.invoke_shell() returns.
        # TODO: In order to preserve python2 compatibility, this uses
        # time.time() for timeouts, which it shouldn't. Switch to
        # time.monotonic() after python2 compat is dropped.
        if self._shell is None:
            raise RuntimeError("cannot receive: not connected.")

        old_timeout = self._shell.timeout
        self._shell.settimeout(timeout)

        output = self._expect(self._shell, match, timeout)
        self._shell.settimeout(old_timeout)
        return output

    @classmethod
    def _expect(cls, channel, match, timeout):
        # XXX: This does not accept regexes as 'match' parameter.
        match_len = len(match)
        matched_overlap_len = 0
        # TODO: After dropping py2 compat, this can be set to b'', so that
        # _read_channel() can be removed.
        output = ''

        if timeout is not None:
            start_time = time()

        while True:
            minimal_read_size = match_len - matched_overlap_len

            if timeout is not None:
                next_read_timeout = cls._get_time_left(start_time, timeout)
                channel.settimeout(next_read_timeout)

            output += cls._read_channel(channel, minimal_read_size)

            if output.endswith(match):
                return output

            matched_overlap_len = cls._length_of_match_overlap(output, match)

    @staticmethod
    def _get_time_left(start_time, timeout):
        elapsed_time = time() - start_time
        if elapsed_time >= timeout:
            raise timeout_exception()
        time_left = timeout - elapsed_time
        return time_left

    @staticmethod
    def _length_of_match_overlap(sequence, pattern):
        """ Return the longest length of suffix of sequence that matches prefix
        of a pattern.
        """
        # TODO: If too slow, this can be optimized using memoization:
        # O(p) -> O(p - last_length)
        if not sequence or not pattern:
            return 0
        while True:
            if sequence.endswith(pattern):
                return len(pattern)
            pattern = pattern[:-1]

    @staticmethod
    def _read_channel(channel, size):
        return channel.recv(size).decode(errors='ignore')
